import React, { useEffect, useState } from "react";
import { Icon } from "@blueprintjs/core";
import { ICompanyMembers } from "stores/company/Reducer";
import { Entity } from "stores/UtilsActions";
import { Form, Field } from "react-final-form";
import { IconNames } from "@blueprintjs/icons";
import { required, checkError } from "components/final-form/utils";
import { Condition } from "components/final-form/Condition";
import { SubmitAndResetButtons } from "components/final-form/SubmitResetButtons";
import { InputGroupFieldWithError } from 'components/fields/InputGroupField';
import { DropdownFieldWithError } from 'components/fields/DropdownField';
interface EditDesignationFormProps {
	setShowDialogEdit: (val: boolean) => void;
}

interface EditDesignationFormInternalProps extends EditDesignationFormProps {
	member: ICompanyMembers | undefined;
	setShowDialogEdit: (val: boolean) => void;
	editDesignation: (values: any, memberId: string) => void;
	getCompanyMembers: () => void;
	divisions: Entity[];
	departments: Entity[];
}
export const EditDesignationForm = (
	props: EditDesignationFormInternalProps
) => {
	const [initial, setInitial] = useState({})

	const onSubmit: any = async (values: any) => {
		if (props.member) {
			values.designation = props.member.designations[0]._id;
			const status: any = await props.editDesignation(values, props.member._id);
			if (status === 200) {
				await props.getCompanyMembers();
				props.setShowDialogEdit(false);
			}
		}
		return {};
	};

	const initialValues: any = () => {
		let divisions = ["director", "cxo"];
		if (props.member && props.member.designations.length) {
			if (divisions.includes(props.member.designations[0].division)) {
				return {
					division: props.member.designations[0].division,
					position: props.member.designations[0].position
				};
			} else {
				return {
					division: props.member.designations[0].division,
					department: props.member.designations[0].department._id,
					position: props.member.designations[0].position
				};
			}
		}
		return {};
	};

	useEffect(() => {
		setInitial(initialValues());
	}, [])


	return (
		<Form
			onSubmit={onSubmit}
			initialValues={initial}
			render={({ handleSubmit, form, submitting, pristine, values }) => (
				<div>
					<div className="flex justify-end pa3">
						<Icon
							icon={IconNames.DELETE}
							iconSize={20}
							className="grow pointer tigrow-lightBlue"
							onClick={(e: any) => props.setShowDialogEdit(false)}
						/>
					</div>
					<form className="fl w-100 pa4 pt0" onSubmit={handleSubmit}>
						<h1 className="f5 tigrow-lightBlue">Edit Role</h1>
						<div className="flex flex-column">
							<div className="mb4">
								<Field<string>
									name="division"
									validate={required}
									render={({ input, meta }) =>
										<DropdownFieldWithError
											id={input.name}
											selectedValue={input.value}
											options={
												props.divisions && props.divisions.length > 0 ?
													props.divisions : [] as any
											}
											onChange={input.onChange}
											leftIcon="id-number"
											error={checkError(meta) && (meta.error || meta.submitError)}
										/>
									}
								/>
							</div>

							<Condition
								when="division"
								validate={(value => {
									return [
										"seniorManager",
										"middleManager",
										"operationalEmployee"
									].includes(value);
								})}
							>
								<div className="mb4">
									<Field<string>
										name="department"
										validate={required}
										render={({ input, meta }) =>
											<>
												<DropdownFieldWithError
													id={input.name}
													selectedValue={input.value}
													options={
														props.departments &&
															props.departments.length > 0 ?
															props.departments : [] as any
													}
													onChange={input.onChange}
													leftIcon="comparison"
													error={checkError(meta) && (meta.error || meta.submitError)}
												/>
											</>
										}
									/>
								</div>
							</Condition>
						</div>
						<Field<string>
							name="position"
							validate={required}
							render={({ input, meta }) =>
								<InputGroupFieldWithError
									id={input.name}
									className={`br0 ${checkError(meta) ? "bb b--red" : "bb b--lightBlue"}`}
									placeHolder="Position"
									value={input.value}
									onChange={input.onChange}
									leftIcon="id-number"
									leftIconColor={`${checkError(meta) ? "red" : "#0fa3a3"}`}
									style={{ boxShadow: "none" }}
									error={checkError(meta) && (meta.error || meta.submitError)}
								/>
							}
						/>
						<SubmitAndResetButtons
							reset={form.reset}
							submitting={submitting}
							pristine={pristine}
							resetBtnName="Reset"
							submitBtnName="Save"
						/>
					</form>
				</div>
			)}
		/>
	);
};
